import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'main': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'rel': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'pkgrel': 'http://schemas.openxmlformats.org/package/2006/relationships',
    'doc': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
}

def col_to_idx(ref):
    letters = ''.join(c for c in ref if c.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch.upper()) - ord('A') + 1)
    return idx - 1

def row_of(ref):
    return int(''.join(c for c in ref if c.isdigit()))

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()

    # workbook -> sheet name mapping
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = [(s.get('name'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
              for s in wb.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}sheet')]

    # rels: rId -> target
    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rel_map = {r.get('Id'): r.get('Target') for r in rels}

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}si'):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for name, rid in sheets:
        target = rel_map.get(rid)
        if not target:
            continue
        if not target.startswith('xl/'):
            target = 'xl/' + target.lstrip('/')
        path = target
        print(f'=== Sheet: {name} ({path}) ===')
        root = ET.fromstring(z.read(path))
        for row in root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            cells = {}
            for c in row.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
                val = v.text if v is not None else ''
                if t == 's' and val != '':
                    val = shared[int(val)]
                elif t == 'b':
                    val = 'TRUE' if val == '1' else 'FALSE'
                elif t == 'inlineStr':
                    is_el = c.find('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}is')
                    val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if is_el is not None else ''
                cells[col_to_idx(ref)] = val
            if cells:
                maxc = max(cells)
                print(row.get('r'), [cells.get(i, '') for i in range(maxc + 1)])
